here::i_am("Code/Figure10.R")

# ============================================================
# Generate Figure 10(a)--(c):
#   Figure 10(a): Beijing
#   Figure 10(b): Shanghai
#   Figure 10(c): Hong Kong
#
# Required inputs:
#   Data/GHCNv4.xlsx
#   Data/Valid/assimilation_Beijing.csv
#   Data/Valid/assimilation_Shanghai.csv
#   Data/Valid/assimilation_HongKong.csv
#
# The validation CSV files are generated by Code/Figure9d.R and
# contain the complete annual assimilation output. Figure 10
# uses only years for which GHCN, assimilated, LME, and calibrated
# REACHES values are all available, ensuring an identical
# comparison period for all three methods.
#
# Outputs:
#   Output/Figure10/Figure10a.png
#   Output/Figure10/Figure10b.png
#   Output/Figure10/Figure10c.png
#   Output/Figure10/Figure10_metrics.csv
#   Output/Figure10/Figure10_correlations.csv
#   Output/Figure10/Figure10_plot_data.csv
# ============================================================

library(readxl)
library(dplyr)
library(tidyr)
library(readr)
library(ggplot2)

# ------------------------------------------------------------
# 1. Paths and display settings
# ------------------------------------------------------------

ghcn_file <- here::here(
  "Data",
  "GHCNv4.xlsx"
)

# Prefer the reconstruction produced in the current run; a checked-in
# Data/Valid snapshot may belong to another documentary-input version.
generated_validation_dir <- here::here(
  "Output", "Intermediate", "Assimilation"
)
generated_city_files <- file.path(
  generated_validation_dir,
  paste0("assimilation_", c("Beijing", "Shanghai", "HongKong"), ".csv")
)
if (nzchar(Sys.getenv("REACHES_VERSIONED_RUN", unset = "")) &&
    !all(file.exists(generated_city_files))) {
  stop("Versioned validation requires all three generated city outputs.")
}
validation_dir <- if (all(file.exists(generated_city_files))) {
  generated_validation_dir
} else {
  here::here("Data", "Valid")
}

output_dir <- here::here(
  "Output",
  "Figure10"
)

dir.create(
  output_dir,
  recursive = TRUE,
  showWarnings = FALSE
)

method_levels <- c(
  "Assimilated",
  "LME",
  "REACHES"
)

# Match the source colours used in Figure 8 and Figure S3.
method_colors <- c(
  "Assimilated" = "black",
  "LME" = "deepskyblue",
  "REACHES" = "firebrick"
)

method_shapes <- c(
  "Assimilated" = 16,
  "LME" = 17,
  "REACHES" = 15
)

base_text_size <- 23
correlation_text_size <- 6.5
legend_text_size <- 18

# ------------------------------------------------------------
# 2. Read the GHCN workbook
#
# The workbook contains repeating value/flag columns. Preserve
# the original selection of year plus 12 monthly temperatures.
# ------------------------------------------------------------

if (!file.exists(
  ghcn_file
)) {
  stop(
    "GHCN workbook was not found: ",
    ghcn_file
  )
}

ghcn_column_types <- c(
  "skip", "numeric", "skip",
  "numeric", "skip", "skip",
  "numeric", "skip", "skip",
  "numeric", "skip", "skip",
  "numeric", "skip", "skip",
  "numeric", "skip", "skip",
  "numeric", "skip", "skip",
  "numeric", "skip", "skip",
  "numeric", "skip", "skip",
  "numeric", "skip", "skip",
  "numeric", "skip", "skip",
  "numeric", "skip", "skip",
  "numeric", "skip", "skip"
)

ghcn_all <- readxl::read_excel(
  ghcn_file,
  col_types = ghcn_column_types
)

if (ncol(
  ghcn_all
) != 13L) {
  stop(
    "Expected one GHCN year column and 12 monthly columns, ",
    "but found ",
    ncol(
      ghcn_all
    ),
    " columns."
  )
}

names(
  ghcn_all
) <- c(
  "year",
  paste0(
    "month",
    1:12
  )
)

# ------------------------------------------------------------
# 3. City configuration
# ------------------------------------------------------------

city_config <- list(
  Beijing = list(
    row_indices = 1:161,
    remove_local_rows = c(
      103,
      104
    ),
    validation_file = file.path(
      validation_dir,
      "assimilation_Beijing.csv"
    ),
    output_file = file.path(
      output_dir,
      "Figure10a.png"
    )
  ),
  Shanghai = list(
    row_indices = 443:503,
    remove_local_rows = integer(
      0
    ),
    validation_file = file.path(
      validation_dir,
      "assimilation_Shanghai.csv"
    ),
    output_file = file.path(
      output_dir,
      "Figure10b.png"
    )
  ),
  HongKong = list(
    row_indices = 839:895,
    remove_local_rows = integer(
      0
    ),
    validation_file = file.path(
      validation_dir,
      "assimilation_HongKong.csv"
    ),
    output_file = file.path(
      output_dir,
      "Figure10c.png"
    )
  )
)

# ------------------------------------------------------------
# 4. Helper functions
# ------------------------------------------------------------

prepare_ghcn_city <- function(
    ghcn_data,
    row_indices,
    remove_local_rows,
    city_name) {

  if (
    length(
      row_indices
    ) == 0L ||
      max(
        row_indices
      ) >
        nrow(
          ghcn_data
        )
  ) {
    stop(
      "The configured GHCN row range for ",
      city_name,
      " is invalid."
    )
  }

  city_data <- ghcn_data[
    row_indices,
    ,
    drop = FALSE
  ]

  if (length(
    remove_local_rows
  ) > 0L) {

    if (
      min(
        remove_local_rows
      ) < 1L ||
        max(
          remove_local_rows
        ) >
          nrow(
            city_data
          )
    ) {
      stop(
        "A configured GHCN row removal for ",
        city_name,
        " is invalid."
      )
    }

    city_data <- city_data[
      -remove_local_rows,
      ,
      drop = FALSE
    ]
  }

  monthly_values <- as.matrix(
    city_data[
      ,
      paste0(
        "month",
        1:12
      ),
      drop = FALSE
    ]
  )

  storage.mode(
    monthly_values
  ) <- "double"

  # Retain only years with all 12 monthly temperatures.
  complete_months <- rowSums(
    is.na(
      monthly_values
    )
  ) == 0L

  annual_temperature <- rowMeans(
    monthly_values,
    na.rm = TRUE
  ) /
    100

  result <- data.frame(
    year = as.integer(
      city_data$year[
        complete_months
      ]
    ),
    GHCN = as.numeric(
      annual_temperature[
        complete_months
      ]
    )
  ) %>%
    arrange(
      year
    )

  if (
    anyNA(
      result
    ) ||
      any(!is.finite(
        result$GHCN
      )) ||
      anyDuplicated(
        result$year
      )
  ) {
    stop(
      "Invalid annual GHCN values were produced for ",
      city_name,
      "."
    )
  }

  result
}

read_validation_data <- function(
    filename,
    city_name) {

  if (!file.exists(
    filename
  )) {
    stop(
      "Validation file for ",
      city_name,
      " was not found: ",
      filename,
      "\nRun Code/Figure9d.R first."
    )
  }

  validation_data <- readr::read_csv(
    filename,
    show_col_types = FALSE
  )

  # Prefer the explicit names produced by the revised Figure9d.R.
  revised_columns <- c(
    "year",
    "smoothed_temperature_celsius",
    "calibrated_reaches_celsius",
    "lme_ensemble_mean_celsius"
  )

  # Retain support for older archived validation files.
  legacy_columns <- c(
    "year",
    "predicted",
    "REACHES",
    "LME"
  )

  if (all(
    revised_columns %in%
      names(
        validation_data
      )
  )) {

    validation_data <- validation_data %>%
      transmute(
        year = as.integer(
          year
        ),
        Assimilated = as.numeric(
          smoothed_temperature_celsius
        ),
        REACHES = as.numeric(
          calibrated_reaches_celsius
        ),
        LME = as.numeric(
          lme_ensemble_mean_celsius
        ),
        Prior_only = if ("prior_mean" %in% names(validation_data)) {
          as.numeric(prior_mean)
        } else {
          NA_real_
        },
        Conditional_variance =
          if ("smoothed_variance" %in% names(validation_data)) {
            as.numeric(smoothed_variance)
          } else {
            NA_real_
          }
      )

  } else if (all(
    legacy_columns %in%
      names(
        validation_data
      )
  )) {

    warning(
      "Using legacy validation column names for ",
      city_name,
      ". Regenerate this file with Code/Figure9d.R."
    )

    validation_data <- validation_data %>%
      transmute(
        year = as.integer(
          year
        ),
        Assimilated = as.numeric(
          predicted
        ),
        REACHES = as.numeric(
          REACHES
        ),
        LME = as.numeric(
          LME
        ),
        Prior_only = NA_real_,
        Conditional_variance = NA_real_
      )

  } else {

    stop(
      filename,
      " must contain either the revised columns:\n  ",
      paste(
        revised_columns,
        collapse = ", "
      ),
      "\nor the legacy columns:\n  ",
      paste(
        legacy_columns,
        collapse = ", "
      ),
      "."
    )
  }

  if (
    anyNA(
      validation_data$year
    ) ||
      anyDuplicated(
        validation_data$year
      )
  ) {
    stop(
      "The validation file contains invalid or duplicated years ",
      "for ",
      city_name,
      "."
    )
  }

  validation_data %>%
    arrange(
      year
    )
}

prepare_common_comparison_data <- function(
    validation_data,
    ghcn_data,
    city_name) {

  joined_data <- inner_join(
    validation_data,
    ghcn_data,
    by = "year"
  )

  # The reviewer requested comparisons at identical years.
  # Therefore, retain only the intersection where all four
  # absolute-temperature series are finite.
  common_data <- joined_data %>%
    filter(
      is.finite(
        GHCN
      ),
      is.finite(
        Assimilated
      ),
      is.finite(
        LME
      ),
      is.finite(
        REACHES
      )
    ) %>%
    arrange(
      year
    )

  if (nrow(
    common_data
  ) < 2L) {
    stop(
      "Fewer than two common complete comparison years were ",
      "found for ",
      city_name,
      "."
    )
  }

  common_data
}

make_long_plot_data <- function(
    common_data,
    city_name) {

  common_data %>%
    pivot_longer(
      cols = all_of(
        method_levels
      ),
      names_to = "Method",
      values_to = "Estimate"
    ) %>%
    mutate(
      city = city_name,
      Method = factor(
        Method,
        levels = method_levels
      )
    )
}

compute_method_metrics <- function(
    plot_data,
    city_name) {

  plot_data %>%
    group_by(
      Method
    ) %>%
    summarise(
      city = city_name,
      number_of_years = n(),
      first_year = min(
        year
      ),
      last_year = max(
        year
      ),
      correlation = cor(
        GHCN,
        Estimate
      ),
      mean_bias_estimate_minus_GHCN = mean(
        Estimate -
          GHCN
      ),
      RMSE = sqrt(
        mean(
          (
            Estimate -
              GHCN
          )^2
        )
      ),
      anomaly_correlation = cor(
        Estimate -
          mean(
            Estimate
          ),
        GHCN -
          mean(
            GHCN
          )
      ),
      anomaly_RMSE = sqrt(
        mean(
          (
            (
              Estimate -
                mean(
                  Estimate
                )
            ) -
              (
                GHCN -
                  mean(
                    GHCN
                  )
              )
          )^2
        )
      ),
      .groups = "drop"
    ) %>%
    mutate(
      Method = factor(
        Method,
        levels = method_levels
      )
    ) %>%
    arrange(
      Method
    )
}

make_square_limits <- function(
    plot_data,
    padding_fraction = 0.05) {

  value_range <- range(
    c(
      plot_data$GHCN,
      plot_data$Estimate
    ),
    finite = TRUE
  )

  value_span <- diff(
    value_range
  )

  if (
    !is.finite(
      value_span
    ) ||
      value_span <= 0
  ) {
    value_span <- max(
      abs(
        value_range
      ),
      1
    )
  }

  padding <- padding_fraction *
    value_span

  c(
    value_range[
      1
    ] -
      padding,
    value_range[
      2
    ] +
      padding
  )
}

make_correlation_labels <- function(
    metrics,
    plot_limits) {

  plot_span <- diff(
    plot_limits
  )

  metrics %>%
    arrange(
      Method
    ) %>%
    mutate(
      label = paste0(
        Method,
        ": Cor = ",
        formatC(
          correlation,
          format = "f",
          digits = 2
        )
      ),
      # Position all correlation labels in the lower-right corner.
      x = plot_limits[2] - 0.03 * plot_span,
      y = plot_limits[1] + c(0.05, 0.12, 0.19) * plot_span
    )
}

make_scatter_plot <- function(
    plot_data,
    correlation_labels,
    plot_limits) {

  ggplot(
    plot_data,
    aes(
      x = GHCN,
      y = Estimate,
      colour = Method,
      shape = Method
    )
  ) +
    geom_point(
      size = 3.5,
      alpha = 0.85
    ) +
    geom_abline(
      intercept = 0,
      slope = 1,
      linetype = "dashed",
      colour = "red",
      linewidth = 0.8
    ) +
    geom_text(
      data = correlation_labels,
      aes(
        x = x,
        y = y,
        label = label,
        colour = Method
      ),
      inherit.aes = FALSE,
      show.legend = FALSE,
      hjust = 1,
      size = correlation_text_size
    ) +
    scale_colour_manual(
      values = method_colors,
      breaks = method_levels
    ) +
    scale_shape_manual(
      values = method_shapes,
      breaks = method_levels
    ) +
    coord_equal(
      xlim = plot_limits,
      ylim = plot_limits
    ) +
    labs(
      x = expression(
        "GHCN temperature (" *
          degree *
          "C)"
      ),
      y = expression(
        "Estimated temperature (" *
          degree *
          "C)"
      ),
      colour = NULL,
      shape = NULL
    ) +
    theme_bw() +
    theme(
      text = element_text(
        size = base_text_size
      ),
      legend.title = element_blank(),
      legend.position = "bottom",
      legend.text = element_text(
        size = legend_text_size
      )
    )
}

# ------------------------------------------------------------
# 5. Generate Figure 10(a)--(c)
# ------------------------------------------------------------

figure10_plots <- vector(
  "list",
  length(
    city_config
  )
)

names(
  figure10_plots
) <- names(
  city_config
)

metric_tables <- vector(
  "list",
  length(
    city_config
  )
)

names(
  metric_tables
) <- names(
  city_config
)

plot_data_tables <- vector(
  "list",
  length(
    city_config
  )
)

names(
  plot_data_tables
) <- names(
  city_config
)

# Retain exact annual comparisons for the additional reviewer tables.
common_year_tables <- setNames(
  vector("list", length(city_config)), names(city_config)
)

for (
  city_name in names(
    city_config
  )
) {

  config <- city_config[[city_name]]

  ghcn_city <- prepare_ghcn_city(
    ghcn_data = ghcn_all,
    row_indices = config$row_indices,
    remove_local_rows =
      config$remove_local_rows,
    city_name = city_name
  )

  validation_data <- read_validation_data(
    filename =
      config$validation_file,
    city_name = city_name
  )

  common_data <-
    prepare_common_comparison_data(
      validation_data =
        validation_data,
      ghcn_data = ghcn_city,
      city_name = city_name
    )

  common_year_tables[[city_name]] <- common_data

  plot_data <- make_long_plot_data(
    common_data = common_data,
    city_name = city_name
  )

  metrics <- compute_method_metrics(
    plot_data = plot_data,
    city_name = city_name
  )

  plot_limits <- make_square_limits(
    plot_data
  )

  correlation_labels <-
    make_correlation_labels(
      metrics = metrics,
      plot_limits = plot_limits
    )

  plot_object <- make_scatter_plot(
    plot_data = plot_data,
    correlation_labels =
      correlation_labels,
    plot_limits = plot_limits
  )

  figure10_plots[[city_name]] <- plot_object

  metric_tables[[city_name]] <- metrics

  plot_data_tables[[city_name]] <- plot_data

  ggsave(
    filename = config$output_file,
    plot = plot_object,
    width = 6,
    height = 6,
    units = "in",
    dpi = 300
  )

  message(
    "Saved ",
    city_name,
    ": ",
    config$output_file,
    " using ",
    nrow(
      common_data
    ),
    " common years."
  )
}

# ------------------------------------------------------------
# 6. Save metrics and exact plotting data
# ------------------------------------------------------------

figure10_metrics <- bind_rows(
  metric_tables
) %>%
  mutate(
    Method = as.character(
      Method
    )
  )

figure10_plot_data <- bind_rows(
  plot_data_tables
) %>%
  mutate(
    Method = as.character(
      Method
    )
  )

readr::write_csv(
  figure10_metrics,
  file.path(
    output_dir,
    "Figure10_metrics.csv"
  )
)

# Preserve a correlation-only file for compatibility with the
# previous workflow.
readr::write_csv(
  figure10_metrics %>%
    dplyr::select(
      city,
      method = Method,
      correlation
    ),
  file.path(
    output_dir,
    "Figure10_correlations.csv"
  )
)

readr::write_csv(
  figure10_plot_data,
  file.path(
    output_dir,
    "Figure10_plot_data.csv"
  )
)

# ------------------------------------------------------------
# 7. Reviewer validation summary: four products and state intervals
# ------------------------------------------------------------

# The "prior-only" mean is the unconditional state mean prior_mean
# from Figure9d.R, not dynamic_prior_prediction (which already uses
# previous REACHES updates). The 95% interval is the conditional
# *latent-state* interval, not a GHCN predictive interval.
reviewer_metrics <- function(data, scope) {
  if (nrow(data) < 2L) return(NULL)
  products <- c(
    "Assimilated" = "Assimilated",
    "REACHES" = "REACHES",
    "LME" = "LME",
    "Prior-only" = "Prior_only"
  )
  do.call(rbind, lapply(names(products), function(product) {
    estimate <- data[[products[[product]]]]
    data.frame(
      scope = scope,
      city = unique(data$city),
      product = product,
      n_years = nrow(data),
      first_year = min(data$year),
      last_year = max(data$year),
      bias_estimate_minus_GHCN = mean(estimate - data$GHCN),
      RMSE = sqrt(mean((estimate - data$GHCN)^2)),
      correlation = stats::cor(estimate, data$GHCN)
    )
  }))
}

reviewer_coverage <- function(data, scope) {
  if (nrow(data) < 1L) return(NULL)
  half_width <- stats::qnorm(0.975) *
    sqrt(data$Conditional_variance)
  data.frame(
    scope = scope,
    city = unique(data$city),
    interval = "conditional_latent_state_95",
    n_years = nrow(data),
    first_year = min(data$year),
    last_year = max(data$year),
    GHCN_inside_95pct = mean(
      data$GHCN >= data$Assimilated - half_width &
      data$GHCN <= data$Assimilated + half_width
    ),
    mean_interval_width_celsius = mean(2 * half_width),
    median_interval_width_celsius = median(2 * half_width)
  )
}

complete_reviewer_rows <- function(data, city_name) {
  missing_columns <- setdiff(
    c("Prior_only", "Conditional_variance"), names(data)
  )
  if (length(missing_columns) > 0L) {
    stop("Missing reviewer metrics for ", city_name,
         ": ", paste(missing_columns, collapse = ", "))
  }
  data %>%
    filter(
      is.finite(Prior_only),
      is.finite(Conditional_variance),
      Conditional_variance >= 0
    ) %>%
    mutate(city = city_name)
}

reviewer_by_city <- Map(
  complete_reviewer_rows,
  common_year_tables, names(common_year_tables)
)
if (any(vapply(reviewer_by_city, nrow, integer(1L)) < 2L)) {
  warning(
    "Some city data lack prior_mean or smoothed_variance. ",
    "Recreate all city assimilation files with Code/Figure9d.R ",
    "before producing the reviewer validation summaries."
  )
} else {
  # Within each city, all four products use exactly the same years.
  city_metrics <- dplyr::bind_rows(
    Map(function(z, city) reviewer_metrics(z, "matched_within_city"),
        reviewer_by_city, names(reviewer_by_city))
  )
  city_coverage <- dplyr::bind_rows(
    Map(function(z, city) reviewer_coverage(z, "matched_within_city"),
        reviewer_by_city, names(reviewer_by_city))
  )
  readr::write_csv(
    city_metrics,
    file.path(output_dir, "Figure10_reviewer_city_metrics.csv")
  )
  readr::write_csv(
    city_coverage,
    file.path(output_dir, "Figure10_reviewer_city_95pct.csv")
  )

  # Also enforce the same calendar years across Beijing, Shanghai,
  # and Hong Kong, when at least two such years are available.
  shared_years <- sort(Reduce(
    intersect, lapply(reviewer_by_city, function(z) z$year)
  ))
  readr::write_csv(
    data.frame(year = shared_years),
    file.path(output_dir, "Figure10_reviewer_shared_years.csv")
  )
  if (length(shared_years) >= 2L) {
    shared_by_city <- lapply(
      reviewer_by_city,
      function(z) z %>% filter(year %in% shared_years)
    )
    shared_metrics <- dplyr::bind_rows(
      lapply(shared_by_city,
             function(z) reviewer_metrics(z, "same_years_all_cities"))
    )
    shared_coverage <- dplyr::bind_rows(
      lapply(shared_by_city,
             function(z) reviewer_coverage(z, "same_years_all_cities"))
    )
    readr::write_csv(
      shared_metrics,
      file.path(output_dir, "Figure10_reviewer_shared_year_metrics.csv")
    )
    readr::write_csv(
      shared_coverage,
      file.path(output_dir, "Figure10_reviewer_shared_year_95pct.csv")
    )
  } else {
    warning(
      "Fewer than two validation years are shared by all three cities. ",
      "City-matched summaries were produced instead."
    )
  }
}

message(
  "Completed Figure 10(a), Figure 10(b), and Figure 10(c)."
)

message(
  "Full correlation, bias, RMSE, and anomaly metrics saved to: ",
  file.path(
    output_dir,
    "Figure10_metrics.csv"
  )
)
